-- ============================================================
-- 근태(attendance) / 연차(leave_balance, leave_grant) 더미 데이터 (com_id = 1 기준)
-- attendance_leave_ddl_v2.sql 로 테이블이 이미 생성되어 있어야 한다.
-- salary_insert.sql(=07_sal_calc_engine_dummy_data.sql)과 동일한 12명 대상, 동일한 급여월(2026-06/07)을 커버한다.
-- salary-module-design.md(2026-08-23) 의 연동 로직 그대로:
--   OvertimeAllowanceCalculator : payMonth 1개월간 attendance.overtime_minutes 합계 x 통상시급(baseSal/209) x 1.5
--   AnnualLeaveAllowanceCalculator : leave_balance(연도별) 의 (total_days - used_days) x 통상일급(시급 x 8)
--
-- *** 중요: 이 파일을 넣으면 salary_insert.sql 의 OVERTIME_ALLOWANCE/ANNUAL_LEAVE_ALLOWANCE(전부 0원 처리)와
-- 더 이상 맞지 않게 된다. 아래 대화 설명대로 salary_insert.sql 도 함께 갱신한 08_salary_insert_v2.sql 를 같이 제공한다. ***
-- ============================================================

SET DEFINE OFF;

-- ------------------------------------------------------------
-- 0) 재실행 안전을 위한 기존 더미 데이터 삭제 + 시퀀스 초기화
--    (attendance_leave_ddl_v2.sql 은 최초 1회 생성 스크립트라 DROP/CREATE 관례가 없지만,
--     이 insert 스크립트는 sal_* 스크립트와 동일하게 재실행 가능하도록 만든다.)
-- ------------------------------------------------------------
DELETE FROM leave_grant;
DELETE FROM leave_balance;
DELETE FROM attendance;

BEGIN EXECUTE IMMEDIATE 'DROP SEQUENCE SEQ_ATTENDANCE'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -2289 THEN RAISE; END IF; END;
/
CREATE SEQUENCE SEQ_ATTENDANCE START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
BEGIN EXECUTE IMMEDIATE 'DROP SEQUENCE SEQ_LEAVE_BALANCE'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -2289 THEN RAISE; END IF; END;
/
CREATE SEQUENCE SEQ_LEAVE_BALANCE START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
BEGIN EXECUTE IMMEDIATE 'DROP SEQUENCE SEQ_LEAVE_GRANT'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -2289 THEN RAISE; END IF; END;
/
CREATE SEQUENCE SEQ_LEAVE_GRANT START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;

-- ------------------------------------------------------------
-- 1) attendance (근태 기록) : 405건
--    6월: 132/135/136/138/141/143 (salary_insert.sql 의 6월 급여 지급 대상과 동일)
--    7월: 12명 전원 (salary_insert.sql 의 7월 급여 지급 대상과 동일)
--    안예준(142)은 입사일(7/4, 토)이 지나 첫 근무일인 7/6(월)부터 근태가 시작된다.
-- ------------------------------------------------------------

-- ------------------------------------------------------------
-- 2) leave_balance (연차 잔여, 2026년) : 12건 (12명 x 1건)
--    입사 1년 미만자 매월 개근 1일 발생(근로기준법 제60조 2항) 기준으로 오늘(2026-08-23)까지의
--    완료된 개월 수만큼 total_days 를 채웠다. 이규우/한도훈은 7월에 연차 1일 사용(used_days=1.00).
-- ------------------------------------------------------------

-- ------------------------------------------------------------
-- 3) leave_grant (연차 부여 이력) : 42건
--    입사월 기준 매 1개월 개근마다 REG(정기부여) 1일씩, 소멸시한은 부여일로부터 1년.
-- ------------------------------------------------------------

COMMIT;